\begin{tikzpicture}[font=\sffamily, thick, scale=1]

  % Battery on the left
  \draw (0,0) to[battery2, l=12\,V] (0,3);

  % Top wire and resistor R
  \draw (0,3) -- (2,3);
  \draw (2,3) to[european resistor, l=$R$] (4,3);
  \draw (4,3) -- (6,3);

  % Right side thermistor T
  \draw (6,3) to[thermistor] (6,0);

  % Bottom wire completing the loop
  \draw (6,0) -- (0,0);

  % Voltmeter across R (connected at x=2 and x=4, y=3)
  \draw (2,3) -- (2,4.5) coordinate (v1);
  \draw (4,3) -- (4,4.5) coordinate (v2);
  \draw (v1) -- (v2) node[midway, above] {};
  \draw (3,4.5) circle (0.35cm) node {V};

  % Junction dots
  \fill (2,3) circle (2pt);
  \fill (4,3) circle (2pt);

  % Label T
  \node[right] at (6.2, 1.5) {$T$};

  % Caption
  \node at (3, -0.8) {Fig. 2.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, thick, scale=1]

  % Battery on the left (IEC standard: alternating long and short lines, here drawn manually or using standard paths)
  % Using standard IEC battery representation (two parallel lines, long positive, short thick negative)
  \draw (0,0) -- (0,1.2);
  \draw[line width=1.5pt] (-0.4,1.2) -- (0.4,1.2); % positive plate
  \draw (-0.25,1.5) -- (0.25,1.5);                % negative plate
  \draw (0,1.5) -- (0,3);
  \node[left] at (-0.4, 1.35) {$12\text{ V}$};

  % Top wire and resistor R (IEC standard rectangle)
  \draw (0,3) -- (2,3);
  \draw (2,2.7) rectangle node[above=2pt] {$R$} (4,3.3);
  \draw (4,3) -- (6,3);

  % Right side thermistor T (IEC resistor rectangle with a diagonal arrow through it)
  \draw (6,3) -- (6,2.1);
  \draw (5.7,0.9) rectangle node[right=4pt] {$T$} (6.3,2.1);
  \draw (5.5,0.7) -- (6.5,2.3);
  \draw[->] (6.1,1.8) -- (6.5,2.2);
  \draw (6,0.9) -- (6,0);

  % Bottom wire completing the loop
  \draw (6,0) -- (0,0);

  % Voltmeter across R (connected at x=2 and x=4, y=3)
  \draw (2,3) -- (2,4.5) coordinate (v1);
  \draw (4,3) -- (4,4.5) coordinate (v2);
  \draw (v1) -- (3,4.5);
  \draw (3,4.5) circle (0.35cm) node {V};
  \draw (3,4.85) -- (3,4.5); % connection to circle top? No, circle centered at (3,4.5)
  \draw (3,4.5) -- (v2);

  % Junction dots
  \fill (2,3) circle (2pt);
  \fill (4,3) circle (2pt);

  % Caption
  \node at (3, -0.8) {Fig. 2.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, thick, scale=1]

  % Battery on the left (multi-cell IEC battery: alternating long thin and short thick lines)
  \draw (0,0) -- (0,1.0);
  % Cell 1 (bottom)
  \draw[line width=1.5pt] (-0.3,1.0) -- (0.3,1.0); % long (+ plate)
  \draw (-0.15,1.2) -- (0.15,1.2);                 % short (- plate)
  % Cell 2
  \draw[line width=1.5pt] (-0.3,1.4) -- (0.3,1.4); % long (+ plate)
  \draw (-0.15,1.6) -- (0.15,1.6);                 % short (- plate)
  % Cell 3
  \draw[line width=1.5pt] (-0.3,1.8) -- (0.3,1.8); % long (+ plate)
  \draw (-0.15,2.0) -- (0.15,2.0);                 % short (- plate)
  % Cell 4 (top)
  \draw[line width=1.5pt] (-0.3,2.2) -- (0.3,2.2); % long (+ plate)
  \draw (-0.15,2.4) -- (0.15,2.4);                 % short (- plate)

  \draw (0,2.4) -- (0,3);
  \node[left] at (-0.4, 1.7) {$12\text{ V}$};

  % Top wire and resistor R (IEC standard rectangle)
  \draw (0,3) -- (2,3);
  \draw (2,2.7) rectangle node[above=0pt] {$R$} (4,3.3);
  \draw (4,3) -- (6,3);

  % Right side thermistor T (IEC resistor rectangle with a diagonal arrow through it)
  \draw (6,3) -- (6,2.1);
  \draw (5.7,0.9) rectangle node[right=4pt] {$T$} (6.3,2.1);
  \draw (5.5,0.7) -- (6.5,2.3);
  \draw[->] (6.1,1.8) -- (6.5,2.2);
  \draw (6,0.9) -- (6,0);

  % Bottom wire completing the loop
  \draw (6,0) -- (0,0);

  % Voltmeter across R (connected at x=2 and x=4, y=3)
  \draw (2,3) -- (2,4.5) -- (2.65,4.5);
  \draw (4,3) -- (4,4.5) -- (3.35,4.5);
  \draw (3,4.5) circle (0.35cm) node {V};

  % Junction dots
  \fill (2,3) circle (2pt);
  \fill (4,3) circle (2pt);

  % Caption
  \node at (3, -0.8) {Fig. 2.1};

\end{tikzpicture}
